// ============================================================
// NOVA v3.0.0 — Orientadora y Gestora de Citas
// Sistema NOVA · SAGE · ATLAS — Pangi
// Erick Del Piero | Mayo 2026
//
// CAMBIOS v3.0.0:
//   - Flujo de agendamiento completo (8 estados nuevos)
//   - Mock DB con estructura lista para swap a MongoDB Azure
//   - Lectura de contexto SAGE (evita preguntas redundantes)
//   - Selección de doctor, slots y confirmación real
//   - Referencia de cita generada (PA-XXXXXX)
// ============================================================

// El nodo previo es ahora la llamada al db_manager (catálogo), así que
// $input trae SU respuesta, no el payload original. El payload sigue
// disponible en el trigger.
const inp = $('📥 Llamada Entrante').first().json;

const REQUIRED = ['userId', 'sessionId', 'remoteJid', 'instance'];
const missing  = REQUIRED.filter(k => !inp[k]);
if (missing.length) {
  return [{ json: { success: false, error: 'MISSING_FIELDS', details: missing } }];
}

// ══════════════════════════════════════════════════════════════
// CAPA DE ADAPTACIÓN DE CATÁLOGOS  (v3.0.1)
// ──────────────────────────────────────────────────────────────
// Punto único donde NOVA obtiene datos que en PRODUCCIÓN son
// propiedad de Pangi (se administran desde admin.pangi.com).
//
// Hoy: devuelven los literales del MVP → comportamiento idéntico.
// Producción: un nodo previo inyecta el catálogo real del API de
// Pangi y estas funciones lo devuelven. Los sitios de uso NO
// cambian. El literal queda como fallback si el API no responde.
//
// ⚠️ Debe devolver EXACTAMENTE el mismo catálogo que SAGE
//    (getCities en 02_sage). Hoy divergen: NOVA incluye
//    'Barranquilla' y usa 'San José'; SAGE usa 'San José, CR' y
//    no tiene Barranquilla. La integración con el catálogo de
//    Pangi elimina esa divergencia — NO parchear a mano.
//
// NOTA: los doctores ya están detrás de accesoras
//   (mockQueryDoctors / mockGetProvider / mockGetSlots),
//   que son su propia capa de adaptación. No se tocan aquí.
// ══════════════════════════════════════════════════════════════

// Ciudades canónicas para búsqueda de doctores y clínicas.
// PRODUCCIÓN: ciudades activas del catálogo de Pangi.
// Acepta tanto ['Lima', ...] como [{n:'Lima', ...}, ...] para ser
// compatible con la forma que devuelva getCities() en SAGE.
function getCities() {
  // 1) Catálogo real de Pangi (tabla pangi_cities, sincronizada cada hora).
  //    Se leen las 36 ciudades con sus dos banderas: el motor decide qué
  //    ofrecer y qué aceptar, y puede distinguir "no existe" de "existe
  //    pero hoy no tiene médicos".
  try {
    const r = $('🗄️ DB — Cargar Catálogo').first().json;
    if (r && r.success === true && Array.isArray(r.data) && r.data.length > 0) {
      return r.data.map(x => x && x.city).filter(Boolean);
    }
  } catch (e) { /* nodo ausente o sin ejecutar → se usa el fallback */ }

  // 2) Inyección directa por input (compatibilidad).
  const c = inp.catalogCities;
  if (Array.isArray(c) && c.length > 0) {
    return c.map(x => (x && typeof x === 'object') ? x.n : x).filter(Boolean);
  }
  return ['Lima','Bogotá','Medellín','Cartagena','Cali','Ciudad de México','Cancún','Monterrey','Guadalajara','Santo Domingo','Buenos Aires','Miami','San José','Barranquilla'];
}

// Perfil básico del paciente (edad, sexo, condiciones, medicamentos).
// Hoy: cache de sesión, compartido con SAGE vía sessionContext.
// PRODUCCIÓN: perfil real de Pangi (patients) por userId.
// PENDIENTE (definir con el contacto técnico backend de Pangi): precedencia si ambos existen.
// Por ahora la sesión gana sobre Pangi (refleja lo último que dijo
// el paciente en el chat). Debe coincidir con SAGE.
function getPatientProfile(ctx) {
  const p = inp.pangiPatientProfile;
  if (p && typeof p === 'object' && !Array.isArray(p)) {
    return { ...p, ...(ctx.patientProfile || {}) };
  }
  return ctx.patientProfile || {};
}

const ctx    = inp.sessionContext || {};
// CONSUMO DEL HANDOFF PENDIENTE (fix del bucle "¿Listo para empezar?"):
// el router dispara ctx.pendingHandoff con prioridad máxima en cada turno; los returns
// de handoff hacían spread de ctx sin limpiarlo → se re-ejecutaba indefinidamente.
// Se consume aquí, en la base común de TODOS los returns. inp.pendingHandoff (el del
// router, ya entregado a este turno) no se toca: el handoff actual sí se ejecuta.
delete ctx.pendingHandoff;
delete ctx.pendingMessage;
const nova   = ctx.nova || {};
const state  = nova.state || 'welcome';
const txt    = (inp.messageText || '').toLowerCase().trim();
const intent = inp.intentDetected || '';
const ph     = inp.pendingHandoff || null;
// Handoff entrante (ej. SAGE→NOVA para agendar): el mensaje original viaja en nova.pendingMessage
const novaPending = nova.pendingMessage || inp.pendingMessage || '';
const fn     = inp.userName ? inp.userName.split(' ')[0] : null;
const nm     = fn ? ` ${fn}` : '';
const isNew  = inp.isNewSession || ['initial', 'initial_presented'].includes(inp.sessionState);
// Detectar idioma del mensaje actual — actualiza si hay señal clara
const _storedLang = inp.detectedLanguage || ctx.language || inp.userLanguage || 'es';
const _msgLang = (() => {
  const t = (inp.messageText || '').toLowerCase().trim();
  // Señales claras de inglés
  if (/\b(hello|hi there|good morning|good evening|yes please|thank you|i want|i need|i have|quote|schedule|compare|how much|can you|my name|i am|i'm|let's|let me|what is|please help)\b/.test(t)) return 'en';
  if (/^(hello|hi|hey|yes|yeah|nope|sure|ok cool|thanks|quote|schedule|compare|good)$/.test(t)) return 'en';
  // Señales claras de portugués
  if (/\b(olá|ola|oi |bom dia|boa tarde|boa noite|obrigad|quero|sim |não |nao |tudo bem|como vai|me ajuda|cotação)\b/.test(t)) return 'pt';
  if (/^(olá|ola|oi|sim|não|nao|obrigado|obrigada)$/.test(t)) return 'pt';
  return null;
})();
const LANG = _storedLang || _msgLang;

const normalize = s => String(s).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').trim();

// Canonicalización de ciudades: alias (CDMX/DF) y tildes correctos SIEMPRE.
// Evita guardar 'Cdmx'/'Bogota' que luego no matchean las clínicas ('Ciudad de México').
const CITY_CANON = getCities();

// ── ALIAS DE CIUDAD ─────────────────────────────────────────
// Reconocimiento de lenguaje, NO catálogo: Pangi no tiene alias y no
// los tendrá. Vive aquí junto al resto de la lógica de matching.
//
// `canon` es una LISTA DE CANDIDATOS en orden de preferencia. El
// destino debe existir en el catálogo activo: con el catálogo de
// Pangi 'cdmx' resuelve a 'Mexico City'; con el literal de fallback
// resuelve a 'Ciudad de México'. El mismo código sirve en ambos
// mundos y por eso el fallback es idéntico al comportamiento previo.
//
// Si ningún candidato existe en el catálogo, el alias se ignora y la
// ciudad simplemente no se reconoce: NOVA vuelve a preguntar en vez
// de inventar un destino que Pangi no acepta.
//
// PENDIENTE (capa 2): 'Buenos Aires' no resuelve contra Pangi, que
// solo tiene los barrios Balvanera/Barracas/Palermo. Se resolverá
// con Claude + caché de resoluciones, no ampliando esta lista a mano.
const CITY_ALIASES = [
  { canon: ['Mexico City', 'Ciudad de México'], al: ['cdmx', 'df', 'ciudad de mexico'] },
  { canon: ['Santo Domingo'],                   al: ['rep dom', 'republica dominicana'] },
  { canon: ['Buenos Aires'],                    al: ['baires', 'caba'] },
];

// Primer candidato del alias que exista en el catálogo activo.
const _aliasTarget = (a) => a.canon.find(cn =>
  CITY_CANON.some(cc => normalize(cc) === normalize(cn))) || null;

const _esc = (s) => String(s).replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

// Expande alias dentro de un texto YA normalizado, hacia el nombre
// que usa el catálogo. Reemplaza el .replace(cdmx|df|mexico city)
// que estaba repetido en cuatro sitios y apuntaba a un literal fijo.
const applyCityAliases = (txtN) => {
  let out = String(txtN || '');
  for (const a of CITY_ALIASES) {
    const target = _aliasTarget(a);
    if (!target) continue;
    for (const raw of a.al) {
      const aN = normalize(raw);
      if (!aN) continue;
      out = out.replace(new RegExp('\\b' + _esc(aN) + '\\b', 'g'), normalize(target));
    }
  }
  return out;
};

// Devuelve el nombre EXACTO del catálogo, o null si no se reconoce.
// El nombre exacto importa: viaja al array `addresses` de Pangi, que
// compara cadenas literales.
const findCity = (raw) => {
  const rN = applyCityAliases(normalize(raw || ''));
  if (!rN) return null;
  return CITY_CANON.find(cc => {
    const cN = normalize(cc);
    return cN === rN || cN.includes(rN) || rN.includes(cN);
  }) || null;
};

const canonCity = (raw) => findCity(raw)
  || (String(raw).charAt(0).toUpperCase() + String(raw).slice(1));
const txtN = normalize(txt);

