const detectSpecialty = t => {
  const n = normalize(t);
  if (/dental|diente|muela|odonto|dentist|extrac|implant|ortodoncia|corona|veneer|blanquea|endodoncia|conducto|tooth|teeth|braces|dente|ortodon|implantol|periodont/.test(n)) return 'dental';
  if (/plastic|rinoplas|liposu|mamario|busto|bichec|blefaroplas|lifting|bbl|glute|mamas|seno|nariz|estetica|estetic|facial|corporal|abdominoplas|otoplas/.test(n)) return 'plastic_surgery';
  if (/^1$/.test(n.trim())) return 'dental';
  if (/^2$/.test(n.trim())) return 'plastic_surgery';
  return null;
};

const detectModality = t => {
  const n = normalize(t);
  if (/presencial|person|clinic|clinica|^1$/.test(n)) return 'presencial';
  if (/video|virtual|remoto|online|tele|^2$/.test(n)) return 'video';
  return null;
};

const specLabel = (sp, lang) => {
  const m = { dental:{es:'🦷 Dental',en:'🦷 Dental',pt:'🦷 Dental'},
               plastic_surgery:{es:'💉 Cirugía Plástica',en:'💉 Plastic Surgery',pt:'💉 Cirurgia Plástica'}};
  return (m[sp] || {})[lang] || sp;
};

const slotDisp = (slot, lang) => {
  if (lang==='en') return slot.dispEn;
  if (lang==='pt') return slot.dispPt;
  return slot.dispEs;
};

