    sched_notes:     `Do you have any notes or message for the doctor? _(optional)_\n\nType your message or *no* to continue without one.`,
    sched_confirm:   `✅ *Confirm your appointment:*\n\n👨‍⚕️ *Doctor:* {doctor}\n🏥 *Specialty:* {spec}\n📍 *Location:* {city}, {country} ({modal})\n📅 *Date & time:* {slot}\n{notes_line}\nAll correct? Type *confirm* to book or *cancel* to exit.`,
    sched_done:      `🎉 *Appointment confirmed${nm}!*\n\n📋 *Reference:* #{ref}\n👨‍⚕️ {doctor}\n📅 {slot}\n📍 {city}\n\nYou'll receive details soon. How else can I help?`,
    sched_cancel:    `Understood${nm}. The booking was cancelled. Type *schedule* whenever you want to try again. How else can I help?`,
    sched_from_sage: `I see you were quoting *{proc}* for *{cities}*. 👀\n\nLooking for a *{spec}* specialist in *{first_city}*?\n\n*Yes* — search with those details\n*No* — search with other options`,
    notes_line_tpl:  `📝 *Note:* {notes}\n`,
