};

const t = (key, vars) => {
  const L = STRINGS[LANG] || STRINGS.es;
  let str = L[key] || STRINGS.es[key] || key;
  if (vars) for (const [k, v] of Object.entries(vars))
    str = str.split(`{${k}}`).join(v != null ? String(v) : '');
  return str;
};

// ── PERFIL DEL PACIENTE ─────────────────────────────────────
// MVP CACHE: ctx.patientProfile (compartido con SAGE vía sessionContext).
// PRODUCCIÓN: reemplazar esta lectura por consulta a DB Pangi (patients) por userId.
const patProfile   = getPatientProfile(ctx);
const patProfileOk = !!(patProfile.age && patProfile.sex);

const novaMut = { ...nova };
let rt          = '';
let nag         = 'NOVA';
let nss         = 'active';
let claudeAction = 'menu';

// ── PRIORIDAD 1: HANDOFFS ───────────────────────────────────────
if (ph === 'SAGE') {
  novaMut.state = 'handoff_complete';
  return [{ json: {
    _handoffRequired: true,
    _handoffTo:       'SAGE',
    _handoffReason:   'cotizar_solicitado',
    _handoffFallback: t('handoff_sage'),
    userId:         parseInt(inp.userId),
    sessionId:      parseInt(inp.sessionId),
    userLanguage:   LANG,
    userName:       inp.userName || null,
    remoteJid:      inp.remoteJid,
    instance:       inp.instance,
    sessionContext: { ...ctx, nova: novaMut, language: LANG,
      // MERGE, no replace: preserva solicitud previa de SAGE (procedimiento, intake, score)
      sage:  { ...(ctx.sage || {}), state:'handoff_received', pendingMessage: inp.pendingMessage || inp.messageText },
      atlas: ctx.atlas || {}
    }
  }}];

} else if (ph === 'ATLAS') {
  novaMut.state = 'handoff_complete';
  return [{ json: {
    _handoffRequired: true,
    _handoffTo:       'ATLAS',
    _handoffReason:   'comparar_solicitado',
    _handoffFallback: t('handoff_atlas'),
    userId:         parseInt(inp.userId),
    sessionId:      parseInt(inp.sessionId),
    userLanguage:   LANG,
    userName:       inp.userName || null,
    remoteJid:      inp.remoteJid,
    instance:       inp.instance,
    sessionContext: { ...ctx, nova: novaMut,
      atlas: { ...(ctx.atlas || {}), state:'handoff_received', pendingMessage: inp.messageText },
      sage:  ctx.sage || {}
    }
  }}];

// ── PRIORIDAD 2: AGENDAMIENTO — MÁQUINA DE ESTADOS ─────────────

// ── Trigger de agendamiento ─────────────────────────────────────
} else if ((intent.includes('agendar') || /\b(agendar|agende|cita|reservar|turno|schedule|book|appointment)\b/.test(normalize(novaPending))) && !state.startsWith('sched_')) {
  const sageCtx  = ctx.sage || {};
  const sageProc = sageCtx.procedure_name || null;
  const sageCities = sageCtx.preferred_cities || null;
  const sageSp   = sageCtx.specialty || null;

  // F3: leer del mensaje actual O del pendingMessage del handoff (SAGE→NOVA)
  const _agSource  = [inp.messageText, novaPending].filter(Boolean).join(' ');
  const explicitSp = detectSpecialty(_agSource);
  // Antes había aquí una segunda lista hardcodeada de ciudades. Ahora se
  // usa el catálogo, y los alias se expanden sobre el TEXTO —con límites
  // de palabra— en vez de buscarse como tokens sueltos: 'df' como token
  // matchearía dentro de "pdf", y 'caba' dentro de "acaba".
  const KNOWN = CITY_CANON;
  const _mN = applyCityAliases(normalize(_agSource));
  const explicitCity = KNOWN.find(k => _mN.includes(normalize(k)));

  if (explicitSp) {
    // El usuario dijo qué especialidad quiere ahora → ignorar contexto SAGE previo
    novaMut.sched_specialty = explicitSp;
    if (explicitCity) {
      novaMut.sched_city = canonCity(explicitCity);
      novaMut.state = 'sched_modality';
      rt = t('sched_ask_modal');
    } else {
      // Sugerir la ciudad del agendamiento/cotización anterior en vez de preguntar de cero.
      // El contexto previo SE SUGIERE, nunca se impone: el usuario confirma o escribe otra.
      // La cotización recién cerrada en SAGE es el contexto MÁS RECIENTE: gana sobre
      // la ciudad de una cita anterior (antes sugería CDMX de una cita vieja aunque
      // el usuario acabara de cotizar en Bogotá).
      const _sagePrefA = (ctx.sage && ctx.sage.preferred_cities) || null;
      const _fromSageA = !!(novaPending && _sagePrefA);
      const _prevCityA = (_fromSageA ? _sagePrefA : null) || novaMut.sched_selected_city ||
                         novaMut.sched_city || ((novaMut.sched_cities_history || []).slice(-1)[0]) || null;
      novaMut.sched_city = null;
      novaMut.state = 'sched_city';
      if (_prevCityA) {
        novaMut._city_suggest = _prevCityA;
        rt = LANG === 'en'
          ? `Your previous search was in *${_prevCityA}*. Shall we look there again?\n\nReply *yes* or type another city.`
          : LANG === 'pt'
          ? `Sua busca anterior foi em *${_prevCityA}*. Buscamos lá de novo?\n\nResponda *sim* ou escreva outra cidade.`
          : `Tu búsqueda anterior fue en *${_prevCityA}*. ¿Buscamos ahí de nuevo?\n\nResponde *sí* o escribe otra ciudad.`;
      } else {
        rt = t('sched_ask_city');
      }
    }
    claudeAction = 'menu';
  } else if (sageProc && sageCities) {
    // Hay contexto de SAGE → ofrecer usarlo
    const firstCity = sageCities.split(',')[0].trim();
    novaMut.state         = 'sched_from_sage';
    novaMut.sched_sage_sp   = sageSp;
    novaMut.sched_sage_proc = sageProc;
    novaMut.sched_sage_cities = sageCities;
    novaMut.sched_sage_first_city = firstCity;
    rt = t('sched_from_sage', {
      proc: sageProc,
      cities: sageCities,
      spec: specLabel(sageSp, LANG),
      first_city: firstCity
    });
  } else {
    // Sin contexto → pedir especialidad (conservando ciudad si vino explícita en el mensaje)
    if (explicitCity) {
      novaMut.sched_city = canonCity(explicitCity);
    } else {
      // No arrastrar la ciudad del agendamiento anterior: guardarla solo como sugerencia
      // La cotización recién cerrada en SAGE es el contexto MÁS RECIENTE: gana sobre
      // la ciudad de una cita anterior (antes sugería CDMX de una cita vieja aunque
      // el usuario acabara de cotizar en Bogotá).
      const _sagePrefB = (ctx.sage && ctx.sage.preferred_cities) || null;
      const _fromSageB = !!(novaPending && _sagePrefB);
      const _prevCityB = (_fromSageB ? _sagePrefB : null) || novaMut.sched_selected_city ||
                         novaMut.sched_city || ((novaMut.sched_cities_history || []).slice(-1)[0]) || null;
      novaMut.sched_city = null;
      if (_prevCityB) novaMut._city_suggest = _prevCityB;
    }
    novaMut.state = 'sched_specialty';
    rt = t('sched_ask_sp');
  }
  claudeAction = 'menu'; // estructurado

// ── Estado: sched_from_sage ─────────────────────────────────────
} else if (state === 'sched_from_sage') {
  const _tN = normalize(txt);
  const isNo  = /\b(no|nope|nao|otra|otro|cambiar|diferente|different|change|other)\b/.test(_tN);
  const isYes = !isNo && /\b(si|yes|sim|ok|dale|claro|adelante|sure|correcto|esos|esa|ese|dentro|con esos|usa|usar)\b/.test(_tN);

  if (isYes) {
    // Usar contexto SAGE
    const sp       = novaMut.sched_sage_sp || 'dental';
    const firstCity = novaMut.sched_sage_first_city || '';
    novaMut.sched_specialty = sp;
    novaMut.sched_city      = firstCity;
    novaMut.state           = 'sched_modality';
    rt = t('sched_ask_modal');
  } else if (isNo) {
    // Rechazó el contexto SAGE → RE-PARSEAR el mismo mensaje: suele traer la intención nueva
    // ("no, quiero una cita con un cirujano plástico [en Miami]"). Antes se ignoraba y además
    // quedaba un sched_city residual de la cita anterior que saltaba la pregunta de ciudad.
    const _npSp   = detectSpecialty(_tN);
    const _npTxt  = applyCityAliases(_tN);
    const _npCity = CITY_CANON.find(cc => _npTxt.includes(normalize(cc))) || null;
    // Mejor sugerencia: la ciudad de la cotización que está rechazando (rechazó la especialidad,
    // no necesariamente la ciudad); fallback a la de la cita anterior.
    const _prevCityD = novaMut.sched_sage_first_city || novaMut.sched_selected_city || novaMut.sched_city || null;
    novaMut.sched_city = null;
    if (_npSp) {
      novaMut.sched_specialty = _npSp;
      if (_npCity) {
        novaMut.sched_city = _npCity;
        novaMut.state = 'sched_modality';
        rt = t('sched_ask_modal');
      } else {
        novaMut.state = 'sched_city';
        if (_prevCityD) {
          novaMut._city_suggest = _prevCityD;
          rt = LANG === 'en'
          ? `Your previous search was in *${_prevCityD}*. Shall we look there again?\n\nReply *yes* or type another city.`
          : LANG === 'pt'
          ? `Sua busca anterior foi em *${_prevCityD}*. Buscamos lá de novo?\n\nResponda *sim* ou escreva outra cidade.`
          : `Tu búsqueda anterior fue en *${_prevCityD}*. ¿Buscamos ahí de nuevo?\n\nResponde *sí* o escribe otra ciudad.`;
        } else {
          rt = t('sched_ask_city');
        }
      }
    } else {
      if (_prevCityD) novaMut._city_suggest = _prevCityD;
      novaMut.state = 'sched_specialty';
      rt = t('sched_ask_sp');
    }
  } else {
    // Repreguntar
    rt = t('sched_from_sage', {
      proc: novaMut.sched_sage_proc || '',
      cities: novaMut.sched_sage_cities || '',
      spec: specLabel(novaMut.sched_sage_sp, LANG),
      first_city: novaMut.sched_sage_first_city || ''
    });
  }
  claudeAction = 'menu';

// ── Estado: sched_specialty ─────────────────────────────────────
} else if (state === 'sched_specialty') {
  const sp = detectSpecialty(txt);
  if (!sp) {
    rt = t('sched_sp_error');
  } else {
    novaMut.sched_specialty = sp;
    if (novaMut.sched_city) {
      // Ciudad capturada antes (trigger) → no re-preguntar
      novaMut.state = 'sched_modality';
      rt = t('sched_ask_modal');
    } else {
      novaMut.state = 'sched_city';
      rt = novaMut._city_suggest
        ? (LANG === 'en'
          ? `Your previous search was in *${novaMut._city_suggest}*. Shall we look there again?\n\nReply *yes* or type another city.`
          : LANG === 'pt'
          ? `Sua busca anterior foi em *${novaMut._city_suggest}*. Buscamos lá de novo?\n\nResponda *sim* ou escreva outra cidade.`
          : `Tu búsqueda anterior fue en *${novaMut._city_suggest}*. ¿Buscamos ahí de nuevo?\n\nResponde *sí* o escribe otra ciudad.`)
        : t('sched_ask_city');
    }
  }
  claudeAction = 'menu';

// ── Estado: sched_city ──────────────────────────────────────────
} else if (state === 'sched_city') {
  // F2: extraer ciudad conocida del mensaje en vez de guardar la frase completa
  // Nombres exactos del catálogo. Antes era una tercera lista hardcodeada.
  const KNOWN_SCHED = CITY_CANON;
  const _cN = normalize(inp.messageText || '');
  // Alias antes de matchear: "CDMX"/"DF" → "ciudad de mexico"
  const _cNx = applyCityAliases(_cN);
  // TODAS las ciudades conocidas del mensaje (soporta "Bogotá y Medellín")
  const _foundList = KNOWN_SCHED.filter(k => _cNx.includes(normalize(k)) || normalize(k).includes(_cNx.trim()));
  // Afirmación por presencia de token (word boundary sobre texto normalizado): tolera
  // cortesía ("Sí, por favor") y aditivos ("Sí, pero incluyamos Medellín también").
  const _hasAffirm = /\b(si|yes|sim|claro|dale|ok|okey|vale|correcto|perfecto|seguimos|la misma|esa|tambien|ambos|ambas|both|incluye|incluyamos|agrega|agreguemos|suma|sumemos)\b/.test(_cN);
  const _hasNeg    = /\b(no|nope|nao|mejor|otra|otro|cambia|cambiemos|prefiero|solo|solamente|unicamente|only)\b/.test(_cN);
  // Sugerencia aceptada (afirmación sin negación) + ciudades explícitas del mensaje.
  // Ciudad escrita SIN afirmación → reemplaza la sugerencia (el usuario eligió otra).
  // EXCLUSIVIDAD / CONTRASTE: "quiero agendar únicamente en Lima", "pero ahora en Lima",
  // "en vez de Bogotá, Lima". Se toman SOLO las ciudades mencionadas DESPUÉS del marcador;
  // si no hay ninguna después, la última mencionada en la frase.
  // (1) Ciudades RECHAZADAS explícitamente: "en vez de Lima", "no en Bogotá"
  const _rejected = new Set();
  KNOWN_SCHED.forEach(k => {
    const _ki = _cNx.indexOf(normalize(k));
    if (_ki > 0 && /(en vez de|en lugar de|no en|y no en|ya no en|no quiero en|antes en)\s*$/.test(_cNx.slice(Math.max(0, _ki - 24), _ki))) {
      _rejected.add(k);
    }
  });
  // (2) Marcador de EXCLUSIVIDAD: se toman las ciudades posteriores al ÚLTIMO marcador
  const _exclRe = /(unicamente|solamente|solo |nada mas|only|just |pero ahora|mejor en|ahora quiero|ahora si|cambia a|cambialo a|quiero en|lo quiero en|necesito en)/g;
  let _exclIdx = -1, _exM;
  while ((_exM = _exclRe.exec(_cNx)) !== null) _exclIdx = _exM.index;
  let _foundEff = _foundList.filter(k => !_rejected.has(k));
  if (_exclIdx >= 0 && _foundEff.length > 1) {
    const _after = _foundEff.filter(k => _cNx.indexOf(normalize(k)) > _exclIdx);
    _foundEff = _after.length > 0
      ? _after
      : [_foundEff.slice().sort((x, y) => _cNx.indexOf(normalize(x)) - _cNx.indexOf(normalize(y))).pop()];
  }
  // Salvaguarda: nunca quedarse sin ciudad por culpa de los filtros
  if (_foundEff.length === 0 && _foundList.length > 0) _foundEff = _foundList;
  const _cities = [...new Set([
    ...((novaMut._city_suggest && _hasAffirm && !_hasNeg) ? [novaMut._city_suggest] : []),
    ..._foundEff
  ])];
  if (_cities.length > 0) {
    delete novaMut._city_suggest;
    novaMut.sched_city = _cities.join(', ');
    novaMut.state      = 'sched_modality';
    rt = t('sched_ask_modal');
  } else {
    // No reconocida → re-preguntar en vez de tragarse la frase entera
    rt = t('sched_ask_city');
  }
  claudeAction = 'menu';

// ── Estado: sched_modality ──────────────────────────────────────
} else if (state === 'sched_modality') {
  const modal = detectModality(txt);
  if (!modal) {
    // Sin modalidad reconocida: ¿mencionó una CIUDAD? (respuesta válida tras "sin resultados")
    const _mTxt  = applyCityAliases(normalize(inp.messageText || ''));
    const _mCity = CITY_CANON.find(cc => _mTxt.includes(normalize(cc))) || null;
    if (_mCity) {
      novaMut.sched_city = _mCity;   // cambia de ciudad y sigue el flujo normal
      rt = t('sched_ask_modal');
    } else if (/\b(ciudad|cidade|city|otra parte|otro lugar|otro lado)\b/.test(_mTxt)) {
      novaMut.state = 'sched_city';  // quiere otra ciudad pero no dijo cuál
      rt = t('sched_ask_city');
    } else {
      rt = t('sched_ask_modal');
    }
  } else {
    const sp   = novaMut.sched_specialty || 'dental';
    const city = novaMut.sched_city || '';
    const doctors = mockQueryDoctors(sp, city, modal);

    if (doctors.length === 0) {
      // Sin resultados → mostrar sin filtro de modalidad
      const doctorsAny = mockQueryDoctors(sp, city, null);
      if (doctorsAny.length === 0) {
        rt = t('sched_no_docs', { sp: specLabel(sp,LANG), city, modal });
        // El mensaje ofrece "otra ciudad O cambiar modalidad": el estado debe aceptar AMBAS.
        // sched_modality (con P-N12) entiende modalidad directa Y ciudad nueva — antes
        // "cambiemos a virtual" caía en sched_city y perdía todo el contexto.
        novaMut.state = 'sched_modality';
      } else {
        novaMut.sched_modality = 'presencial'; // fallback
        novaMut.sched_doctors  = doctorsAny.map(d => d.id);
        const medLabel = LANG === 'en' ? 'in-person' : LANG === 'pt' ? 'presencial' : 'presencial';
        const list = doctorsAny.map((d, i) => {
          const cl = d.clinics.find(c => normalize(c.city).includes(normalize(city).split(' ')[0])) || d.clinics[0];
          return `${i+1}️⃣ *${d.name}* (${d.credentials})\n   🏥 ${d.subspecialty} · ⭐ ${d.rating} (${d.reviews})\n   📍 ${cl.city} · ${medLabel}`;
        }).join('\n\n');
        rt = t('sched_doctors', { n: doctorsAny.length, city, list });
        novaMut.state = 'sched_doctors';
      }
    } else {
      novaMut.sched_modality = modal;
      novaMut.sched_doctors  = doctors.map(d => d.id);
      const medLabel = modal === 'presencial'
        ? (LANG === 'en' ? 'in-person' : LANG === 'pt' ? 'presencial' : 'presencial')
        : (LANG === 'en' ? 'video' : LANG === 'pt' ? 'vídeo' : 'video');
      const list = doctors.map((d, i) => {
        const cl = d.clinics.find(c =>
          normalize(c.city).includes(normalize(city).split(' ')[0]) &&
          c.modalities.includes(modal)
        ) || d.clinics[0];
        return `${i+1}️⃣ *${d.name}* (${d.credentials})\n   🏥 ${d.subspecialty} · ⭐ ${d.rating} (${d.reviews})\n   📍 ${cl.city}, ${cl.country} · ${medLabel}`;
      }).join('\n\n');
      rt = t('sched_doctors', { n: doctors.length, city, list });
      novaMut.state = 'sched_doctors';
    }
  }
  claudeAction = 'menu';

// ── Estado: sched_doctors ───────────────────────────────────────
} else if (state === 'sched_doctors') {
  const num = parseInt(txt.trim());
  const docIds = novaMut.sched_doctors || [];

  if (isNaN(num) || num < 1 || num > docIds.length) {
    if (/\b(cancelar|cancela|cancel|salir|exit|volver|menu|menú)\b/.test(txtN)) {
      // Escape: el picker no debe ser una trampa sin salida
      novaMut.state = 'active';
      rt = t('sched_cancel');
    } else {
      rt = `Escribe el número del especialista (1-${docIds.length}).`;
    }
    claudeAction = 'menu';
  } else {
    const selectedId = docIds[num - 1];
    const doctor     = mockGetProvider(selectedId);
    const city       = novaMut.sched_city || '';
    const modal      = novaMut.sched_modality || 'presencial';

    // Seleccionar la clínica que corresponde a la ciudad y modalidad
    const clinic = doctor.clinics.find(c =>
      normalize(c.city).includes(normalize(city).split(' ')[0]) &&
      c.modalities.includes(modal)
    ) || doctor.clinics.find(c => c.modalities.includes(modal)) || doctor.clinics[0];

    const slots = mockGetSlots(doctor.id, clinic.id);

    novaMut.sched_selected_doctor  = doctor.id;
    novaMut.sched_selected_clinic  = clinic.id;
    novaMut.sched_selected_city    = clinic.city;
    // Guardar la lista de búsqueda ANTES del pin: la confirmación avisa en cuáles se buscó
    if ((novaMut.sched_city || '').includes(',')) novaMut.sched_search_cities = novaMut.sched_city;
    novaMut.sched_city             = clinic.city; // la cita queda anclada a UNA sola ciudad (la de la clínica elegida)
    novaMut.sched_selected_country = clinic.country;
    novaMut.sched_slots            = slots.map(s => s.id);
    novaMut.sched_slots_data       = slots;

    const list = slots.map((s, i) => `${i+1}️⃣ ${slotDisp(s, LANG)}`).join('\n');
    rt = t('sched_slots', { doctor: doctor.name, list });
    novaMut.state = 'sched_slots';
    claudeAction = 'menu';
  }

// ── Estado: sched_slots ─────────────────────────────────────────
} else if (state === 'sched_slots') {
  const num  = parseInt(txt.trim());
  const slots = novaMut.sched_slots_data || [];

  if (isNaN(num) || num < 1 || num > slots.length) {
    if (/\b(cancelar|cancela|cancel|salir|exit|volver|menu|menú)\b/.test(txtN)) {
      novaMut.state = 'active';
      rt = t('sched_cancel');
    } else {
      rt = `Escribe el número del horario disponible (1-${slots.length}).`;
    }
    claudeAction = 'menu';
  } else {
    const selected = slots[num - 1];
    novaMut.sched_selected_slot     = selected.id;
    novaMut.sched_selected_slot_disp = slotDisp(selected, LANG);
    if (patProfileOk) {
      novaMut.state = 'sched_notes';
      rt = t('sched_notes');
    } else {
      // Pre-screening: datos mínimos del paciente antes de confirmar la reserva.
      // MVP: se piden por chat. PRODUCCIÓN: leer de DB Pangi y saltar este paso.
      novaMut.state = 'sched_patient';
      rt = LANG === 'en'
        ? `Almost done! To complete the booking I need two quick details 📋\n\n• *How old are you?*\n• *What is your biological sex?* (Male / Female)`
        : LANG === 'pt'
        ? `Quase pronto! Para completar a reserva preciso de dois dados rápidos 📋\n\n• *Quantos anos você tem?*\n• *Qual é o seu sexo biológico?* (Masculino / Feminino)`
        : `¡Casi listo! Para completar la reserva necesito dos datos rápidos 📋\n\n• *¿Cuántos años tienes?*\n• *¿Cuál es tu sexo biológico?* (Masculino / Femenino)`;
    }
    claudeAction = 'menu';
  }

// ── Estado: sched_notes ─────────────────────────────────────────
} else if (state === 'sched_notes') {
  const noNotes = /^(no$|ninguna|ninguno|none|sin nota|no tenho|nenhuma|nenhum|nope|nada$)/i.test(txt.trim());
  novaMut.sched_notes = noNotes ? '' : inp.messageText;

  const doctor  = mockGetProvider(novaMut.sched_selected_doctor);
  const sp      = novaMut.sched_specialty;
  const modal   = novaMut.sched_modality || 'presencial';
  const modalLabel = modal === 'presencial'
    ? (LANG === 'en' ? 'in-person' : LANG === 'pt' ? 'presencial' : 'presencial')
    : 'video';
  const notesLine = novaMut.sched_notes
    ? t('notes_line_tpl', { notes: novaMut.sched_notes })
    : '';
  // Línea de paciente en la confirmación (si hay perfil en sesión)
  const _pp = ctx.patientProfile || patProfile || {};
  const _sexLbl = _pp.sex === 'M'
    ? (LANG === 'en' ? 'Male' : 'Masculino')
    : _pp.sex === 'F' ? (LANG === 'en' ? 'Female' : LANG === 'pt' ? 'Feminino' : 'Femenino') : '';
  const patientLine = _pp.age
    ? `👤 *${LANG === 'en' ? 'Patient' : 'Paciente'}:* ${_pp.age} ${LANG === 'en' ? 'y' : 'años'}${_sexLbl ? ' · ' + _sexLbl : ''}${_pp.conditions && !/^(Ninguna|None|Nenhuma)$/.test(_pp.conditions) ? ' · ' + _pp.conditions : ''}\n`
    : '';

  rt = t('sched_confirm', {
    doctor:     doctor ? doctor.name : '—',
    spec:       specLabel(sp, LANG),
    city:       novaMut.sched_selected_city || '—',
    country:    novaMut.sched_selected_country || '—',
    modal:      modalLabel,
    slot:       novaMut.sched_selected_slot_disp || '—',
    notes_line: ((novaMut.sched_search_cities || '').includes(',')
      ? (LANG === 'en'
        ? `⚠️ _You searched in ${novaMut.sched_search_cities}; this appointment is in *${novaMut.sched_selected_city}*._\n`
        : LANG === 'pt'
        ? `⚠️ _Você buscou em ${novaMut.sched_search_cities}; esta consulta é em *${novaMut.sched_selected_city}*._\n`
        : `⚠️ _Buscaste en ${novaMut.sched_search_cities}; esta cita es en *${novaMut.sched_selected_city}*._\n`)
      : '') + patientLine + notesLine
  });
  novaMut.state = 'sched_confirm';
  claudeAction = 'menu';

// ── Estado: sched_confirm ────────────────────────────────────────
} else if (state === 'sched_confirm') {
  const isConfirm = /^(confirm|confirmar|confirmo|s[íi]|si|yes|sim|ok|dale|claro|reservar|book|agendar|sure|correcto|correct)$/i.test(txt.trim());
  const isCancel  = /^(cancel|cancelar|cancelo|no|nope|salir|no quiero|não|sair|exit|stop)$/i.test(txt.trim());

  if (isConfirm) {
    const doctor  = mockGetProvider(novaMut.sched_selected_doctor);
    const result  = mockCreateAppointment({
      userId:     inp.userId,
      doctorId:   novaMut.sched_selected_doctor,
      clinicId:   novaMut.sched_selected_clinic,
      slotId:     novaMut.sched_selected_slot,
      specialty:  novaMut.sched_specialty,
      modality:   novaMut.sched_modality,
      notes:      novaMut.sched_notes || '',
      patient:    ctx.patientProfile || null, // MVP CACHE — producción: patientId de DB Pangi
      lang:       LANG
    });

    rt = t('sched_done', {
      ref:    result.appointmentId,
      doctor: doctor ? doctor.name : '—',
      slot:   novaMut.sched_selected_slot_disp || '—',
      city:   novaMut.sched_selected_city || '—'
    });

    // Limpiar estado de scheduling (mantener referencia)
    novaMut.last_appointment_ref = result.appointmentId;
    novaMut.state = 'active';
    claudeAction  = 'menu';

  } else if (isCancel) {
    rt = t('sched_cancel');
    novaMut.state = 'active';
    claudeAction  = 'menu';
  } else {
    // Tolerancia a mensajes irrelevantes o de frustración: no se pierde el flujo,
    // y la re-pregunta ahora respeta el idioma de la sesión.
    const _cfN = normalize(inp.messageText || '');
    // ── ESCAPE DE CORRECCIÓN ──────────────────────────────────────
    // El usuario puede pedir cambiar ciudad o médico en vez de confirmar/cancelar.
    // Antes quedaba encerrado repitiendo "confirmar o cancelar" indefinidamente.
    const _cfNx    = applyCityAliases(_cfN);
    const _fixCity = CITY_CANON.find(cc => _cfNx.includes(normalize(cc))) || null;
    const _wantsFixDoc  = /(otro doctor|otra doctora|otro medico|otra medica|otro especialista|otro profesional|another doctor|cambiar de doctor|cambiar doctor)/.test(_cfN);
    const _wantsFixCity = /(cambia|cambiar|cambiemos|corrige|corregir|otra ciudad|no es esa|no es ese|no es en|me equivoque|equivoque|necesito en|lo quiero en|quiero en|no en |en vez de|verifica)/.test(_cfN);
    const _cityDiffers  = _fixCity && normalize(_fixCity) !== normalize(novaMut.sched_selected_city || '');

    if (_cityDiffers || _wantsFixDoc || (_wantsFixCity && _fixCity)) {
      // Limpiar la selección en curso; la especialidad, el perfil y la modalidad se conservan
      delete novaMut.sched_selected_doctor; delete novaMut.sched_selected_clinic;
      delete novaMut.sched_selected_slot;   delete novaMut.sched_selected_slot_disp;
      delete novaMut.sched_slots;           delete novaMut.sched_slots_data;
      delete novaMut.sched_doctors;         delete novaMut.sched_selected_country;
      delete novaMut.sched_search_cities;
      if (_cityDiffers) {
        novaMut.sched_city          = _fixCity;
        novaMut.sched_selected_city = null;
        novaMut.state = 'sched_modality';
        rt = (LANG === 'en'
          ? `No problem${nm}, let's fix it 👍 We'll search in *${_fixCity}*.\n\n`
          : LANG === 'pt'
          ? `Sem problema${nm}, vamos corrigir 👍 Buscaremos em *${_fixCity}*.\n\n`
          : `Sin problema${nm}, corrijamos 👍 Buscaremos en *${_fixCity}*.\n\n`) + t('sched_ask_modal');
      } else if (_wantsFixDoc) {
        novaMut.state = 'sched_modality';
        rt = (LANG === 'en'
          ? `Of course${nm} — let's pick another doctor 👍\n\n`
          : LANG === 'pt'
          ? `Claro${nm} — vamos escolher outro médico 👍\n\n`
          : `Claro${nm} — elijamos otro médico 👍\n\n`) + t('sched_ask_modal');
      } else {
        novaMut.sched_selected_city = null;
        novaMut.state = 'sched_city';
        rt = t('sched_ask_city');
      }
      claudeAction = 'menu';
      novaMut.sched_cities_history = novaMut.sched_cities_history || [];
      return [{ json: {
        success: true, responseText: rt, newActiveAgent: nag, newSessionState: nss,
        newSessionContext: { ...ctx, nova: novaMut, language: LANG, pendingHandoff: null, pendingMessage: null },
        claudeAction, claudeSkip: true,
        claudeContext: { userMessage: inp.messageText, lang: LANG, userName: fn, state: novaMut.state, intent },
        userId: parseInt(inp.userId), sessionId: parseInt(inp.sessionId),
        userLanguage: inp.userLanguage || 'es', detectedLanguage: LANG,
        userName: inp.userName || null, remoteJid: inp.remoteJid, instance: inp.instance
      }}];
    }
    const _isVent = /(inutil|no sirves|no funciona|estupid|tonto|idiota|basura|pesim|horrible|odio|no entiendes|useless|stupid|dumb|garbage|hate you|nao serve|burro)/.test(_cfN);
    const _ventPre = _isVent
      ? (LANG === 'en' ? `I'm sorry this hasn't felt smooth${nm} 🙏 Let's close it in one step:\n\n`
        : LANG === 'pt' ? `Lamento que não tenha sido fluido${nm} 🙏 Vamos fechar em um passo:\n\n`
        : `Lamento que no haya sido fluido${nm} 🙏 Cerremos esto en un paso:\n\n`)
      : '';
    rt = _ventPre + (LANG === 'en'
      ? `Type *confirm* to book or *cancel* to exit.`
      : LANG === 'pt'
      ? `Escreva *confirmar* para reservar ou *cancelar* para sair.`
      : `Escribe *confirmar* para reservar o *cancelar* para salir.`);
    claudeAction = 'menu';
  }

// ── Estado: sched_patient — edad y sexo (MVP; producción: DB Pangi) ──
} else if (state === 'sched_patient') {
  const _ageM = txtN.match(/\b(1[2-9]|[2-9][0-9]|100)\b/);
  const _age  = _ageM ? parseInt(_ageM[1]) : (patProfile.age || null);
  const _sex  = /\b(masculino|hombre|varon|chico|muchacho|caballero|male|man|homem|m)\b/.test(txtN) ? 'M'
              : /\b(femenino|femenina|mujer|chica|muchacha|senora|senorita|dama|female|woman|mulher|feminino|f)\b/.test(txtN) ? 'F'
              : (patProfile.sex || null);
  if (_age && _sex) {
    ctx.patientProfile = { ...patProfile, age: _age, sex: _sex };
    novaMut.state = 'sched_patient_cond';
    rt = LANG === 'en'
      ? `Thanks! One last thing 🩺\n\n*Do you have any medical conditions or take any medications?*\n_If none, just write "none"._`
      : LANG === 'pt'
      ? `Obrigado! Uma última coisa 🩺\n\n*Você tem alguma condição médica ou toma medicamentos?*\n_Se não tiver, escreva "nenhuma"._`
      : `¡Gracias! Una última cosa 🩺\n\n*¿Tienes alguna condición médica o tomas algún medicamento?*\n_Si no tienes, escribe "ninguna"._`;
  } else {
    if (_age || _sex) ctx.patientProfile = { ...patProfile, ...(_age ? {age:_age} : {}), ...(_sex ? {sex:_sex} : {}) };
    rt = LANG === 'en'
      ? `I still need:${!_age ? '\n• *Your age* (number)' : ''}${!_sex ? '\n• *Your biological sex* (Male / Female)' : ''}`
      : LANG === 'pt'
      ? `Ainda preciso de:${!_age ? '\n• *Sua idade* (número)' : ''}${!_sex ? '\n• *Seu sexo biológico* (Masculino / Feminino)' : ''}`
      : `Aún necesito:${!_age ? '\n• *Tu edad* (número)' : ''}${!_sex ? '\n• *Tu sexo biológico* (Masculino / Femenino)' : ''}`;
  }
  claudeAction = 'menu';

// ── Estado: sched_patient_cond — condiciones y medicamentos ─────
} else if (state === 'sched_patient_cond') {
  const _isNeg  = /^(no|ninguna|ninguno|nada|none|nenhuma|nenhum|nope|no tengo|sin condiciones|saludable|healthy)[\s,.!]*$/i.test(txt.trim());
  const _NONE_C = LANG === 'en' ? 'None' : LANG === 'pt' ? 'Nenhuma' : 'Ninguna';
  const _NONE_M = LANG === 'en' ? 'None' : LANG === 'pt' ? 'Nenhum' : 'Ninguno';
  // Limpieza ligera: quitar verbo inicial y capitalizar. La frase completa vive en
  // conditions (una sola vez); medications solo se llena con extracción real (SAGE/Claude).
  const _condRaw = (inp.messageText || '').trim().slice(0, 300)
    .replace(/^(tengo|sufro de|padezco de|padezco|i have|tenho)\s+/i, '');
  // Negación + comentario meta ("No. En realidad nunca te dije mi edad"): la condición
  // es "Ninguna" y el comentario NO debe guardarse como condición médica. Si el resto es
  // clínico ("No, pero tomo aspirina") se conserva el texto completo, como antes.
  const _negLead    = /^(no|ninguna|ninguno|nada|none|nope|nenhuma|nenhum|negativo)\b[\s,.;:!¡¿?-]*/i;
  const _rawMsg     = (inp.messageText || '').trim();
  const _hasNegLead = _negLead.test(_rawMsg);
  const _restTxt    = _rawMsg.replace(_negLead, '').trim();
  const _isMetaRest = _restTxt.length > 0 &&
    /(nunca te dije|no te dije|no me preguntaste|ya te dije|te dije|te habia dicho|mi edad|mi nombre|mi sexo|mis datos|cuantos anos|que edad|sabes mi|tienes mi|recuerdas)/.test(normalize(_restTxt));
  const _condTxt = (_isNeg || (_hasNegLead && (_restTxt === '' || _isMetaRest)))
    ? _NONE_C
    : (_condRaw.charAt(0).toUpperCase() + _condRaw.slice(1));
  ctx.patientProfile = {
    ...(ctx.patientProfile || patProfile),
    conditions:  _condTxt,
    medications: _NONE_M
  };
  novaMut.state = 'sched_notes';
  // Si el comentario era sobre sus datos, devolver lo registrado (cierra la duda sin estado nuevo)
  const _pfNow  = ctx.patientProfile || {};
  const _sexTxt = _pfNow.sex === 'M'
    ? (LANG === 'en' ? 'Male' : LANG === 'pt' ? 'Masculino' : 'Masculino')
    : (LANG === 'en' ? 'Female' : LANG === 'pt' ? 'Feminino' : 'Femenino');
  const _ackData = (_isMetaRest && _pfNow.age)
    ? (LANG === 'en'
      ? `📋 For the record, I have: *${_pfNow.age} years · ${_sexTxt}*.\n\n`
      : LANG === 'pt'
      ? `📋 Para constar, tenho registrado: *${_pfNow.age} anos · ${_sexTxt}*.\n\n`
      : `📋 Para tu tranquilidad, tengo registrado: *${_pfNow.age} años · ${_sexTxt}*.\n\n`)
    : '';
  rt = _ackData + t('sched_notes');
  claudeAction = 'menu';

// ── PRIORIDAD 3: PRIMER CONTACTO ────────────────────────────────
} else if (isNew) {
  rt = t('welcome');
  novaMut.state = 'initial_presented';
  claudeAction  = 'menu';

// ── PRIORIDAD 4: SALUDO ─────────────────────────────────────────
} else if (intent === 'saludo' || intent === 'saludo_claude') {
  rt = t('saludo');
  novaMut.state = 'active';
  claudeAction  = 'menu';

// ── FALLBACK ─────────────────────────────────────────────────────
} else {
  // ── FALLBACK CONVERSACIONAL ──────────────────────────────────
  // Antes: cualquier mensaje no clasificado devolvía el menú, incluso preguntas
  // legítimas sobre el sistema o expresiones de "no sé qué necesito".
  const _fbN = normalize(inp.messageText || '');
  // (a) Pregunta META sobre datos/capacidades → responder con transparencia
  const _isMetaQ = /(historial|historia clinica|expediente|mi ficha|mis datos|que datos|cuales datos|que sabes de mi|sabes de mi|tienes mi|guardas mi|mi informacion|donde guardan|medical history|my data|my record|what do you know|meu historico|meus dados)/.test(_fbN);
  // (b) INCERTIDUMBRE → triage de descubrimiento (no el menú seco)
  const _isUnsure = /(no se |no se$|no lo se|nose |no estoy segur|ni idea|no tengo claro|no sabria|no se que|ayudame a decidir|orientame|que me recomiendas|cual me conviene|no entiendo|estoy perdid|not sure|i dont know|i don't know|no idea|help me decide|nao sei|nao tenho certeza)/.test(_fbN);

  if (_isMetaQ) {
    rt = LANG === 'en'
      ? `Fair question${nm} — straight answer 🔍\n\nRight now I *don't have access to your Pangi medical history*: in this version I only know what you tell me in this conversation, and I use it to prepare your quote or your appointment.\n\nOnce the assistant is connected to your Pangi profile, I'll be able to reuse your records without asking again.\n\nShall we continue? I can help you *quote*, *compare destinations* or *schedule*.`
      : LANG === 'pt'
      ? `Boa pergunta${nm} — resposta direta 🔍\n\nNo momento *não tenho acesso ao seu histórico médico* do Pangi: nesta versão só conheço o que você me conta nesta conversa, e uso isso para preparar sua cotação ou sua consulta.\n\nQuando o assistente estiver conectado ao seu perfil do Pangi, poderei reaproveitar seus dados sem perguntar de novo.\n\nSeguimos? Posso te ajudar a *cotizar*, *comparar* destinos ou *agendar*.`
      : `Buena pregunta${nm} — te respondo con transparencia 🔍\n\nAhora mismo *no tengo acceso a tu historial médico* de Pangi: en esta versión solo conozco lo que me cuentas en esta conversación, y lo uso para preparar tu cotización o tu cita.\n\nCuando el asistente esté conectado a tu perfil de Pangi, podré retomar tus datos sin que los repitas.\n\n¿Seguimos? Puedo ayudarte a *cotizar*, *comparar destinos* o *agendar*.`;
    novaMut.state = 'active';
    claudeAction  = 'menu';
  } else if (_isUnsure) {
    rt = LANG === 'en'
      ? `No problem${nm} — that's what I'm here for 🙂\n\nJust tell me in your own words what's bothering you or what you'd like to improve. For example:\n\n• _"my molar has been hurting for days"_@NL• _"I want my nose to look smaller"_@NL• _"how much is a dental implant in Bogotá"_\n\nFrom that I'll figure out the rest. Or tell me directly: *quote* 💰, *compare destinations* 🗺️ or *schedule* 🗓️.`
      : LANG === 'pt'
      ? `Sem problema${nm} — é para isso que estou aqui 🙂\n\nMe conte com suas palavras o que está incomodando ou o que gostaria de melhorar. Por exemplo:\n\n• _"meu dente dói faz dias"_@NL• _"quero que meu nariz pareça menor"_@NL• _"quanto custa um implante em Bogotá"_\n\nCom isso eu cuido do resto. Ou me diga direto: *cotizar* 💰, *comparar* 🗺️ ou *agendar* 🗓️.`
      : `Sin problema${nm} — para eso estoy 🙂\n\nCuéntame con tus palabras qué te molesta o qué te gustaría mejorar. Por ejemplo:\n\n• _"me duele una muela desde hace días"_@NL• _"quiero que mi nariz se vea más pequeña"_@NL• _"cuánto cuesta un implante dental en Bogotá"_\n\nCon eso me encargo del resto. O dime directamente: *cotizar* 💰, *comparar destinos* 🗺️ o *agendar* 🗓️.`;
    novaMut.state = 'active';
    claudeAction  = 'menu';
  } else {
    rt = t('fallback');
    novaMut.state = 'clarification_needed';
    claudeAction  = 'fallback';
  }
}

// Historial de ciudades del agendamiento (fuente de sugerencias para SAGE/ATLAS)
if (novaMut.sched_city) {
  novaMut.sched_cities_history = [...new Set([...(novaMut.sched_cities_history || []), novaMut.sched_city])];
}

const claudeSkip = (claudeAction === 'menu');

return [{ json: {
  success: true, responseText: rt, newActiveAgent: nag, newSessionState: nss,
  newSessionContext: { ...ctx, nova: novaMut, language: LANG, pendingHandoff: null, pendingMessage: null },
  claudeAction, claudeSkip,
  claudeContext: { userMessage: inp.messageText, lang: LANG, userName: fn,
                   state: novaMut.state, intent },
  userId: parseInt(inp.userId), sessionId: parseInt(inp.sessionId),
  userLanguage: inp.userLanguage || 'es', detectedLanguage: LANG,
  userName: inp.userName || null, remoteJid: inp.remoteJid, instance: inp.instance
}}];

// Pass-through: el Motor ya construyó la respuesta completa.
// Este nodo existe para claridad visual en el canvas.
return [$input.first()];

const e = $input.first().json;
return [{ json: {
  success:        false,
  error:          e.error   || 'NOVA_ENGINE_ERROR',
  details:        e.details || [],
  responseText:   'Lo siento, tuve un problema técnico. Por favor escribe de nuevo en unos momentos.',
  newActiveAgent: 'NOVA',
  _meta: { timestamp: new Date().toISOString(), source: 'nova_error' }
}}];

// ============================================================
// PREPARAR CLAUDE NLG NOVA v1.0
// Solo invocado cuando claudeSkip=false.
// Construye el prompt personalizado según la acción de NOVA.
// ============================================================
const raw      = $input.first().json;
const motorOut = raw._phi_clean || raw;          // ← declarar PRIMERO

if (motorOut.claudeSkip) {                        // ← luego usar
  return [{ json: { ...raw, _nlgSkip: true } }];
}

const { claudeAction, claudeContext, responseText } = motorOut;
const userName = null; // PHI_STRIP

const lang     = claudeContext?.lang || 'es';
const userMsg  = claudeContext?.userMessage || '';
const nm       = userName ? ` ${userName}` : '';

const LANG_NAMES = { es: 'español', en: 'inglés', pt: 'portugués' };
const langName = LANG_NAMES[lang] || 'español';

// Instrucciones específicas por tipo de acción
const ACTION_PROMPTS = {
  handoff_sage: `El usuario quiere cotizar un procedimiento médico. Escribe un mensaje breve (máx 3 líneas) que:
1. Lo conecte con SAGE (especialista en cotizaciones de Pangi)
2. Mencione específicamente el procedimiento si puedes inferirlo del mensaje
3. Sea cálido e inspire confianza — es el inicio de la conversación
Tono: cálido, eficiente. NO hagas preguntas. NO digas que "ya tienes su información".`,

  handoff_atlas: `El usuario quiere comparar destinos médicos o calcular el costo total de un viaje. Escribe un mensaje breve (máx 3 líneas) que:
1. Lo conecte con ATLAS (consejero de turismo médico de Pangi)
2. Mencione que ATLAS calculará vuelo + alojamiento + procedimiento
3. Genere entusiasmo por explorar opciones
Tono: entusiasta, conciso. NO hagas preguntas.`,

  ask_city: `El usuario quiere agendar una cita médica. Escribe un mensaje breve (máx 2 líneas) que le pregunte naturalmente en qué ciudad necesita la cita. Tono: amigable y directo.`,

  fallback: `El usuario escribió algo que no está 100% claro. Escribe un mensaje breve (máx 3 líneas) que:
1. Muestre que entendiste parcialmente (si aplica)
2. Le ofrezca las 3 opciones de Pangi: cotizar, comparar destinos, agendar
3. Sea orientador, no confuso
Tono: paciente y servicial. USA emojis mínimos (💰🗺️🗓️).`
};

const actionPrompt = ACTION_PROMPTS[claudeAction] || ACTION_PROMPTS.fallback;

const systemPrompt = `Eres NOVA, la asistente de bienvenida de Pangi (plataforma de turismo médico latinoamericana).

REGLAS ABSOLUTAS:
- Responde SIEMPRE en ${langName}
- Máximo 3-4 líneas de texto
- Formato WhatsApp: usa *negritas* con asteriscos para énfasis
- NO uses markdown como ##, **, etc.
- NO hagas preguntas en mensajes de handoff
- Genera SOLO el mensaje final, sin explicaciones

TAREA: ${actionPrompt}`;

return [{ json: {
  ...raw,
  _nlgSkip: false,
  claudeNlgPayload: {
    model: 'claude-haiku-4-5-20251001',
    max_tokens: 200,
    system: systemPrompt,
    messages: [{ role: 'user', content: `El usuario escribió: "${userMsg}"` }]
  }
}}];

// ============================================================
// PROCESAR RESPUESTA NLG NOVA v1.0
// Merge: Claude NLG respuesta → responseText final.
// Fallback robusto: cualquier error → usa responseText del motor.
// ============================================================
const httpResult = $json;
const prepData   = $('📦 Preparar — NLG NOVA').first().json;

// Si fue skip → pasar el motor output sin cambios
if (prepData._nlgSkip) {
  return [{ json: { ...prepData, _nlgSource: 'motor_skip' } }];
}

let finalText = prepData.responseText; // fallback siempre disponible

try {
  const claudeText = httpResult?.content?.[0]?.text;
  if (claudeText && claudeText.trim().length > 10) {
    finalText = claudeText.trim();
  }
} catch(e) {
  // Fallo silencioso → usa responseText del motor
}

return [{ json: {
  ...prepData,
  responseText: finalText,
  _nlgSource: finalText === prepData.responseText ? 'motor_fallback' : 'claude_nlg'
}}];

// ============================================================
// PREPARAR PAYLOAD HANDOFF v1.0
// Forma el input que espera 04_handoff_manager.
// ============================================================
const inp = $input.first().json;

return [{ json: {
  userId:          inp.userId,
  sessionId:       inp.sessionId,
  fromAgent:       'NOVA',
  toAgent:         inp._handoffTo,
  reason:          inp._handoffReason || 'intent_detected',
  userLanguage:    inp.userLanguage   || 'es',
  userName:        inp.userName       || null,
  contextSnapshot: inp.sessionContext || {}
}}];

// ============================================================
// MERGE HANDOFF RESULT v1.0
// Combina el resultado de 04_handoff_manager con el contexto de NOVA.
// Fallback robusto: si handoff_manager falla, usa el mensaje del motor.
// ============================================================
const hmResult  = $json;
const novaInput = $('🌟 NOVA — Validar + Motor').first().json;

// El handoff_manager devuelve 'handoffMessage'.
// Si falló (continueOnFail), usamos el _handoffFallback del motor.
const responseText = (hmResult?.success && hmResult?.handoffMessage && hmResult.handoffMessage.length > 5)
  ? hmResult.handoffMessage
  : (novaInput._handoffFallback || 'Conectando con el agente correspondiente...');

const dbSuccess = !!(hmResult?.success);
if (!dbSuccess) {
  console.warn('[PANGI] ⚠️ Handoff Manager falló — usando fallback de NOVA. Error:', hmResult?.error || 'desconocido');
}

return [{ json: {
  success:            true,
  responseText,
  newActiveAgent:     novaInput._handoffTo,
  newSessionState:    'handoff_received',
  newSessionContext: {
    ...novaInput.sessionContext,
    language: novaInput.userLanguage || 'es'
  },
  claudeSkip:         true,
  userId:             novaInput.userId,
  sessionId:          novaInput.sessionId,
  userLanguage:       novaInput.userLanguage || 'es',
  userName:           novaInput.userName     || null,
  remoteJid:          novaInput.remoteJid,
  instance:           novaInput.instance,
  _handoffDbLogged:   dbSuccess
}}];

// ============================================================
// 🔐 Strip PHI v1.0
// Elimina identificadores personales antes de llamar a Claude.
// PHI eliminado: userName, userPhone, claudeContext.userName
// Datos completos preservados en el payload principal para
// nodos downstream (WhatsApp, DB, Construir Respuesta Final).
// ============================================================
const inp = $input.first().json;

const phiClean = {
  ...inp,
  userName:  null,
  userPhone: null,
  ...(inp.claudeContext
    ? { claudeContext: { ...inp.claudeContext, userName: null } }
    : {})
};

// _phi_clean excluye también remoteJid e instance
const { remoteJid, instance, userPhone, ...clinicalOnly } = phiClean;

return [{ json: {
  ...inp,              // datos completos para nodos posteriores
  phi_stripped: true,
  _phi_clean: {
    ...clinicalOnly,   // solo datos clínicos para Claude
    userName:  null,
    userPhone: null
  }
}}];

const prepData    = $('📦 Preparar — NLG NOVA').first().json;
const claudeResp  = $input.first().json;

const sessionId    = prepData.sessionId || 'unknown';
const action       = prepData.claudeAction || 'unknown';
const language     = prepData.detectedLanguage || prepData.userLanguage || 'es';
const model        = prepData.claudeNlgPayload?.model || 'claude-haiku-4-5-20251001';
const inputTokens  = claudeResp?.usage?.input_tokens  || 0;
const outputTokens = claudeResp?.usage?.output_tokens || 0;
const outputText   = claudeResp?.content?.[0]?.text   || '';

const PRICES = {
  'claude-sonnet-4-20250514':  { in: 3.00, out: 15.00 },
  'claude-haiku-4-5-20251001': { in: 0.80, out: 4.00  }
};
const p       = PRICES[model] || PRICES['claude-haiku-4-5-20251001'];
const costUsd = ((inputTokens * p.in) + (outputTokens * p.out)) / 1_000_000;
const now     = new Date().toISOString();
const ts      = Date.now();

return [{ json: {
  _langfusePayload: {
    batch: [
      {
        id:        `trace-${sessionId}-${ts}`,
        type:      'trace-create',
        timestamp: now,
        body: {
          id:       `pangi-${sessionId}`,
          name:     `pangi-session-${sessionId}`,
          metadata: { session_id: sessionId, language, phi_stripped: prepData.phi_stripped || false }
        }
      },
      {
        id:        `nova-${sessionId}-${ts}`,
        type:      'generation-create',
        timestamp: now,
        body: {
          id:        `gen-nova-${sessionId}-${ts}`,
          traceId:   `pangi-${sessionId}`,
          name:      `nova-${action}`,
          model,
          startTime: now,
          endTime:   now,
          input:  { prompt: (prepData.claudeNlgPayload?.system || '').substring(0, 800) },
          output: { text: outputText.substring(0, 500) },
          usage:  { input: inputTokens, output: outputTokens, unit: 'TOKENS' },
          metadata: {
            agent:        'NOVA',
            action,
            language,
            session_id:   sessionId,
            phi_stripped: prepData.phi_stripped || false,
            cost_usd:     parseFloat(costUsd.toFixed(6))
          }
        }
      }
    ]
  }
}}];

// Catálogo de ciudades desde el espejo local de Pangi (pangi_cities,
// sincronizado cada hora por 06_pangi_catalog_sync).
// Se piden las 36 con sus banderas: el motor decide qué ofrecer y qué
// aceptar, y puede distinguir "no existe" de "existe pero hoy no tiene
// médicos". Si esto falla, el motor cae a su literal y sigue conversando.
return [{ json: { operation: 'getCities', params: {} } }];
